const gen = $('Get Generation').first().json;
const tpl = $input.all().map((i) => i.json).find((r) => r.slug === 'qc_prompt');
if (!tpl || !tpl.body) throw new Error('no active qc_prompt template in prompt_templates');
const magic = ($('Prompt Engine').first().json || {}).magic_prompt_json || {};
// QC checks exactly the text the prompt asked for (the engine's text slot); the brief snapshot is the fallback
const src = Array.isArray((magic.text || {}).lines) ? magic.text.lines : ((gen.brief_snapshot && Array.isArray(gen.brief_snapshot.print_text)) ? gen.brief_snapshot.print_text : ((gen.cards && gen.cards.print_text) || []));
let lines = src.map((t) => String((t && t.text) || '').trim()).filter(Boolean);
if (!Array.isArray((magic.text || {}).lines) && gen.kind === 'edit_text' && gen.old_text && gen.new_text) lines = lines.map((l) => (l === String(gen.old_text).trim() ? String(gen.new_text).trim() : l));
const sc = gen.style_card_snapshot || {}, card = gen.cards || {}, rules = sc.rules || {}, imageUrl = $('Load Config').first().json.sbUrl + '/storage/v1' + String($('Sign Result').first().json.signedURL || '');
// qc_prompt v2 tokens: EXPECTED_SUBJECT = the engine's SUBJECT block; PALETTE_RULE from rules.palette_mode; FORBID_LIST numbered (only text demands dropped - @handles, social/media/instagram/ig/tiktok handles, hashtag/tagline/slogan, EST. + digits - as the style-card-check validator TEXT_DEMAND_RE does; negated visual bans such as No gradients, watermarks or a mug handle stay); STYLE_CARD_JSON pruned, palette = the palette_variants entry for the garment side
const side = /black|navy|charcoal|dark/i.test(String(card.garment_color || '')) ? 'dark' : 'light', variant = (Array.isArray(sc.palette_variants) ? sc.palette_variants : []).find((v) => v && v.garment === side);
const forbid = (Array.isArray(sc.forbid) ? sc.forbid : []).map((f) => String(f || '').trim()).filter((f) => f && !/@\w+|\b(?:social|media|instagram|ig|tiktok)[\s-]+handles?\b|hashtag|tagline|slogan|\bEST\.?\s*\d/i.test(f));
const pruned = { medium: sc.medium, realism: sc.realism, linework: sc.linework, shading: sc.shading, shading_method: sc.shading_method, texture: sc.texture, edge_finish: sc.edge_finish, palette: variant ? { garment: variant.garment, hexes: variant.hexes } : sc.palette, composition: sc.composition, typography: sc.typography, rules };
const paletteRule = rules.palette_mode === 'flexible' ? 'true unless a LARGE, obvious area uses a colour clearly outside the palette - small natural accents are allowed' : 'true only when every colour in the artwork belongs to the palette or is a shade of one; small natural details count';
const vars = { EXPECTED_TEXT: lines.join('\n'), TEXT_LINES: lines.length ? lines.join('\n') : 'NONE', TEXT_LINES_JSON: JSON.stringify(lines), EXPECTED_SUBJECT: String((magic.subject || {}).text || (gen.brief_snapshot || {}).subject || (card.client_submission || {}).subject || ''), PALETTE_RULE: paletteRule, FORBID_LIST: forbid.map((f, i) => (i + 1) + '. ' + f).join('; ') || 'none', STYLE_CARD_JSON: JSON.stringify(pruned), PALETTE_JSON: JSON.stringify(sc.palette || []), GARMENT_COLOR: card.garment_color || '' };
let text = String(tpl.body).replace(/\{\{\s*([A-Z_]+)\s*\}\}/g, (m, k) => (k in vars ? vars[k] : m));
if (!lines.length) text = text.replace(/EXPECTED ON-DESIGN TEXT: """[\s\S]*?"""/, 'EXPECTED ON-DESIGN TEXT: (none - the image must contain NO text at all)');
if (!/STYLE_CARD_JSON|PALETTE_JSON/.test(tpl.body)) text += '\n\nSTYLE CARD (the locked look for this client, JSON below). Add two keys to your JSON: "palette_ok" (' + paletteRule + ') and "style_violations" (array of short strings, [] when none: only a forbidden element from "forbid", or a palette problem). These style keys NEVER change "pass" or the 9 checks. Letter case, font and wording of the text are defined ONLY by the EXPECTED ON-DESIGN TEXT above - never report them as a violation.\n' + JSON.stringify(Object.assign({}, pruned, { forbid }));
if (!/EXPECTED_TEXT|TEXT_LINES/.test(tpl.body)) text += '\n\nEXACT TEXT LINES (each must appear verbatim, exactly once):\n' + vars.TEXT_LINES;
return { json: { body: { messages: [{ role: 'user', content: [{ type: 'text', text }, { type: 'image_url', image_url: { url: imageUrl } }] }], response_format: { type: 'json_object' } }, text_lines: lines, expected_text: lines.join('\n'), expected_subject: vars.EXPECTED_SUBJECT, image_url: imageUrl, template_version: tpl.version } };
